function ZZBase64.enty(text)
local len = _ENV[X("\x4F\x48\x4E\x55\x52\x5B")][X("\x50\x59\x52")](text)
local left = len % 3
len = len - left
local res = {}
local index  = 1
for i = 1, len, 3 do
local a = _ENV[X("\x4F\x48\x4E\x55\x52\x5B")][X("\x5E\x45\x48\x59")](text, i )
local b = _ENV[X("\x4F\x48\x4E\x55\x52\x5B")][X("\x5E\x45\x48\x59")](text, i + 1)
local c = _ENV[X("\x4F\x48\x4E\x55\x52\x5B")][X("\x5E\x45\x48\x59")](text, i + 2)
-- num = a<<16 + b<<8 + c
local num = a * 65536 + b * 256 + c 
for j = 1, 4 do
--tmp = num >> ((4 -j) * 6)
local tmp = _ENV[X("\x51\x5D\x48\x54")][X("\x5A\x50\x53\x53\x4E")](num / (2 ^ ((4-j) * 6)))
--curPos = tmp&0x3f
local curPos = tmp % 64 + 1
res[index] = ZZBase64.__ty[curPos]
index = index + 1
end
end
if left == 1 then
ZZBase64.__left1(res, index, text, len)
elseif left == 2 then
ZZBase64.__left2(res, index, text, len)       
end
return _ENV[X("\x48\x5D\x5E\x50\x59")][X("\x5F\x53\x52\x5F\x5D\x48")](res)
end
function ZZBase64.__left2(res, index, text, len)
local num1 = _ENV[X("\x4F\x48\x4E\x55\x52\x5B")][X("\x5E\x45\x48\x59")](text, len + 1)
num1 = num1 * 1024 --lshift 10 
local num2 = _ENV[X("\x4F\x48\x4E\x55\x52\x5B")][X("\x5E\x45\x48\x59")](text, len + 2)
num2 = num2 * 4 --lshift 2 
local num = num1 + num2
local tmp1 = _ENV[X("\x51\x5D\x48\x54")][X("\x5A\x50\x53\x53\x4E")](num / 4096) --rShift 12
local curPos = tmp1 % 64 + 1
res[index] = ZZBase64.__ty[curPos]
local tmp2 = _ENV[X("\x51\x5D\x48\x54")][X("\x5A\x50\x53\x53\x4E")](num / 64)
curPos = tmp2 % 64 + 1
res[index + 1] = ZZBase64.__ty[curPos]
curPos = num % 64 + 1
res[index + 2] = ZZBase64.__ty[curPos]
res[index + 3] = X("\x01") 
end
function ZZBase64.__left1(res, index,text, len)
local num = _ENV[X("\x4F\x48\x4E\x55\x52\x5B")][X("\x5E\x45\x48\x59")](text, len + 1)
num = num * 16 
tmp = _ENV[X("\x51\x5D\x48\x54")][X("\x5A\x50\x53\x53\x4E")](num / 64)
local curPos = tmp % 64 + 1
res[index ] = ZZBase64.__ty[curPos]
curPos = num % 64 + 1
res[index + 1] = ZZBase64.__ty[curPos]
res[index + 2] = X("\x01") 
res[index + 3] = X("\x01") 
end
